package com.bananalab.lite;
import java.util.*;
/** Actual backprop through all four layers; small local dataset and bounded update. */
final class DeepPixelTrainer{
 static float[][] activations(PixelGenerator m,float[] input){float[][] a=new float[5][];a[0]=input;for(int l=0;l<4;l++){a[l+1]=HeadTrainer.logits(a[l],m.weights[l],m.biases[l]);for(int j=0;j<a[l+1].length;j++)a[l+1][j]=l==3?HeadTrainer.sigmoid(a[l+1][j]):Math.max(0,a[l+1][j]);}return a;}
 static double loss(PixelGenerator m,List<HeadTrainer.Pixel> rows){double loss=0;for(HeadTrainer.Pixel row:rows){float[] p=m.forward(row.x);for(int j=0;j<4;j++){double e=p[j]-row.y[j];loss+=e*e*(j==3?1:row.y[3]);}}return loss/Math.max(1,rows.size()*4);}
 static void step(PixelGenerator m,HeadTrainer.Pixel row,float rate){float[][] a=activations(m,row.x);float[] d=new float[4];for(int j=0;j<4;j++){float p=a[4][j];d[j]=.5f*(p-row.y[j])*p*(1-p)*(j==3?1:row.y[3]);}for(int l=3;l>=0;l--){float[] previous=new float[a[l].length];if(l>0)for(int i=0;i<previous.length;i++){float sum=0;for(int j=0;j<d.length;j++)sum+=m.weights[l][i][j]*d[j];previous[i]=a[l][i]>0?sum:0;}for(int i=0;i<a[l].length;i++)for(int j=0;j<d.length;j++)m.weights[l][i][j]-=rate*a[l][i]*d[j];for(int j=0;j<d.length;j++)m.biases[l][j]-=rate*d[j];d=previous;}}
 static float[][][] copy(PixelGenerator m){float[][][] out=new float[4][][];for(int l=0;l<4;l++)out[l]=HeadTrainer.copy(m.weights[l]);return out;}
 static float[][] biases(PixelGenerator m){float[][] out=new float[4][];for(int l=0;l<4;l++)out[l]=m.biases[l].clone();return out;}
 static double distance(PixelGenerator m,float[][][] old){double n=0;for(int l=0;l<4;l++){double d=HeadTrainer.distance(m.weights[l],old[l]);n+=d*d;}return Math.sqrt(n);}
 static void train(PixelGenerator m,List<HeadTrainer.Pixel> rows,List<HeadTrainer.Pixel> replay){float[][][] old=copy(m);float[][] b=biases(m);for(int epoch=0;epoch<2;epoch++)for(int i=0;i<rows.size();i++){if(Thread.currentThread().isInterrupted())throw new IllegalStateException("Entrenamiento cancelado");step(m,rows.get(i),.002f);if(!replay.isEmpty())step(m,replay.get(i%replay.size()),.002f);}double norm=0;for(int l=0;l<4;l++){double d=HeadTrainer.distance(m.weights[l],old[l]);norm+=d*d;for(int j=0;j<b[l].length;j++){double z=m.biases[l][j]-b[l][j];norm+=z*z;}}norm=Math.sqrt(norm);if(norm>.03){float scale=(float)(.03/norm);for(int l=0;l<4;l++){for(int i=0;i<m.weights[l].length;i++)for(int j=0;j<m.biases[l].length;j++)m.weights[l][i][j]=old[l][i][j]+scale*(m.weights[l][i][j]-old[l][i][j]);for(int j=0;j<m.biases[l].length;j++)m.biases[l][j]=b[l][j]+scale*(m.biases[l][j]-b[l][j]);}}}
}
